 1→import type { Writable, Readable } from 'node:stream'
 2→
 3→export function nodeToWebWritable(nodeStream: Writable): WritableStream<Uint8Array> {
 4→  return new WritableStream<Uint8Array>({
 5→    write(chunk) {
 6→      return new Promise<void>((resolve, reject) => {
 7→        nodeStream.write(Buffer.from(chunk), (err) => {
 8→          if (err) reject(err)
 9→          else resolve()
10→        })
11→      })
12→    },
13→  })
14→}
15→
16→export function nodeToWebReadable(nodeStream: Readable): ReadableStream<Uint8Array> {
17→  return new ReadableStream<Uint8Array>({
18→    start(controller) {
19→      nodeStream.on('data', (chunk: Buffer) => {
20→        controller.enqueue(new Uint8Array(chunk))
21→      })
22→      nodeStream.on('end', () => controller.close())
23→      nodeStream.on('error', (err) => controller.error(err))
24→    },
25→  })
26→}
